initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#history-tbody");
  const pageSize = 20;
  let currentPage = 1;
  let totalPages = 1;
  let allHistories = [];
  let filteredHistories = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const users = await window.aivicApi.list(0); // ログインユーザーテーブル
      const userSelect = container.querySelector("#user-filter");
      if (users) {
        users.forEach(user => {
          const option = document.createElement("option");
          option.value = user.ユーザーID;
          option.textContent = user.ユーザー名;
          userSelect.appendChild(option);
        });
      }
    } catch (error) {
      window.aivicNotify.error("ユーザー一覧の取得に失敗しました");
    }
  }

  // 操作履歴一覧を取得
  async function loadHistories() {
    try {
      const histories = await window.aivicApi.list(15); // 操作履歴テーブル
      allHistories = histories || [];
      applyFilters();
    } catch (error) {
      window.aivicNotify.error("操作履歴の取得に失敗しました");
    }
  }

  // 操作履歴一覧の再描画
  function renderHistories(histories) {
    const startIndex = (currentPage - 1) * pageSize;
    const endIndex = startIndex + pageSize;
    const pageHistories = histories.slice(startIndex, endIndex);

    tbody.innerHTML = pageHistories.map(history => `
      <tr data-id="${history.操作履歴ID}">
        <td>${formatDateTime(history.操作日時)}</td>
        <td>${getUserName(history.ユーザーID)}</td>
        <td>${history.操作種別 || ""}</td>
        <td>${history.操作画面 || ""}</td>
        <td>${history.IPアドレス || ""}</td>
        <td><span class="status-badge ${getResultClass(history.処理結果)}">${history.処理結果 || ""}</span></td>
        <td>${history.処理時間 ? history.処理時間 + "ms" : ""}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${history.操作履歴ID}">詳細</button>
        </td>
      </tr>
    `).join("");

    updatePagination(histories.length);
  }

  // 日時フォーマット
  function formatDateTime(dateTime) {
    if (!dateTime) return "";
    const date = new Date(dateTime);
    return date.toLocaleString("ja-JP");
  }

  // ユーザー名取得
  function getUserName(userId) {
    if (!userId || !tables[0]) return "";
    const user = tables[0].records.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : "";
  }

  // 処理結果のクラス取得
  function getResultClass(result) {
    switch(result) {
      case "成功": return "success";
      case "失敗": return "error";
      case "エラー": return "error";
      default: return "";
    }
  }

  // ページネーション更新
  function updatePagination(totalCount) {
    totalPages = Math.ceil(totalCount / pageSize);
    container.querySelector("#page-info").textContent = `${currentPage} / ${totalPages}`;
    container.querySelector("#btn-prev").disabled = currentPage <= 1;
    container.querySelector("#btn-next").disabled = currentPage >= totalPages;
  }

  // 検索フィルター適用
  function applyFilters() {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const userFilter = container.querySelector("#user-filter").value;
    const operationFilter = container.querySelector("#operation-filter").value;
    const resultFilter = container.querySelector("#result-filter").value;

    filteredHistories = allHistories.filter(history => {
      // 日付フィルター
      if (startDate) {
        const historyDate = new Date(history.操作日時);
        const filterStartDate = new Date(startDate);
        if (historyDate < filterStartDate) return false;
      }
      if (endDate) {
        const historyDate = new Date(history.操作日時);
        const filterEndDate = new Date(endDate);
        filterEndDate.setHours(23, 59, 59, 999);
        if (historyDate > filterEndDate) return false;
      }

      // ユーザーフィルター
      if (userFilter && history.ユーザーID !== userFilter) return false;

      // 操作種別フィルター
      if (operationFilter && history.操作種別 !== operationFilter) return false;

      // 処理結果フィルター
      if (resultFilter && history.処理結果 !== resultFilter) return false;

      return true;
    });

    currentPage = 1;
    renderHistories(filteredHistories);
  }

  // 詳細表示
  function showHistoryDetail(historyId) {
    const history = allHistories.find(h => h.操作履歴ID === historyId);
    if (!history) {
      window.aivicNotify.error("操作履歴が見つかりません");
      return;
    }

    const detailHtml = `
      <div class="detail-modal">
        <div class="detail-content">
          <h3>操作履歴詳細</h3>
          <div class="detail-grid">
            <div class="detail-item">
              <label>操作日時:</label>
              <span>${formatDateTime(history.操作日時)}</span>
            </div>
            <div class="detail-item">
              <label>ユーザー:</label>
              <span>${getUserName(history.ユーザーID)}</span>
            </div>
            <div class="detail-item">
              <label>操作種別:</label>
              <span>${history.操作種別 || ""}</span>
            </div>
            <div class="detail-item">
              <label>操作画面:</label>
              <span>${history.操作画面 || ""}</span>
            </div>
            <div class="detail-item">
              <label>IPアドレス:</label>
              <span>${history.IPアドレス || ""}</span>
            </div>
            <div class="detail-item">
              <label>処理結果:</label>
              <span class="status-badge ${getResultClass(history.処理結果)}">${history.処理結果 || ""}</span>
            </div>
            <div class="detail-item">
              <label>処理時間:</label>
              <span>${history.処理時間 ? history.処理時間 + "ms" : ""}</span>
            </div>
            <div class="detail-item full-width">
              <label>詳細情報:</label>
              <pre>${history.詳細情報 || ""}</pre>
            </div>
          </div>
          <div class="detail-actions">
            <button class="action-btn secondary close-detail-btn">閉じる</button>
          </div>
        </div>
      </div>
    `;

    const modalContainer = document.createElement("div");
    modalContainer.innerHTML = detailHtml;
    document.body.appendChild(modalContainer);

    // 閉じるボタンのイベント
    modalContainer.querySelector(".close-detail-btn").addEventListener("click", () => {
      document.body.removeChild(modalContainer);
    });

    // モーダル背景クリックで閉じる
    modalContainer.addEventListener("click", (e) => {
      if (e.target === modalContainer) {
        document.body.removeChild(modalContainer);
      }
    });
  }

  // CSVエクスポート
  function exportToCsv() {
    try {
      const headers = ["操作日時", "ユーザー名", "操作種別", "操作画面", "IPアドレス", "処理結果", "処理時間", "詳細情報"];
      const csvData = [
        headers.join(","),
        ...filteredHistories.map(history => [
          `"${formatDateTime(history.操作日時)}"`,
          `"${getUserName(history.ユーザーID)}"`,
          `"${history.操作種別 || ""}"`,
          `"${history.操作画面 || ""}"`,
          `"${history.IPアドレス || ""}"`,
          `"${history.処理結果 || ""}"`,
          `"${history.処理時間 ? history.処理時間 + "ms" : ""}"`,
          `"${(history.詳細情報 || "").replace(/"/g, '""')}"`
        ].join(","))
      ].join("\n");

      const blob = new Blob([csvData], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      const url = URL.createObjectURL(blob);
      link.setAttribute("href", url);
      link.setAttribute("download", `操作履歴_${new Date().toISOString().slice(0, 10)}.csv`);
      link.style.visibility = "hidden";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      window.aivicNotify.success("CSVファイルをダウンロードしました");
    } catch (error) {
      window.aivicNotify.error("CSVエクスポートに失敗しました");
    }
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 検索ボタン
    const searchBtn = container.querySelector("#search-btn");
    if (searchBtn) {
      searchBtn.addEventListener("click", applyFilters);
    }

    // リセットボタン
    const resetBtn = container.querySelector("#reset-btn");
    if (resetBtn) {
      resetBtn.addEventListener("click", () => {
        container.querySelector("#start-date").value = "";
        container.querySelector("#end-date").value = "";
        container.querySelector("#user-filter").value = "";
        container.querySelector("#operation-filter").value = "";
        container.querySelector("#result-filter").value = "";
        applyFilters();
      });
    }

    // CSVエクスポートボタン
    const exportBtn = container.querySelector("#export-btn");
    if (exportBtn) {
      exportBtn.addEventListener("click", exportToCsv);
    }

    // ページネーション
    const prevBtn = container.querySelector("#btn-prev");
    const nextBtn = container.querySelector("#btn-next");

    if (prevBtn) {
      prevBtn.addEventListener("click", () => {
        if (currentPage > 1) {
          currentPage--;
          renderHistories(filteredHistories);
        }
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener("click", () => {
        if (currentPage < totalPages) {
          currentPage++;
          renderHistories(filteredHistories);
        }
      });
    }

    // 詳細ボタン（イベント委譲）
    tbody.addEventListener("click", (e) => {
      if (e.target.classList.contains("detail-btn")) {
        const historyId = e.target.getAttribute("data-id");
        showHistoryDetail(historyId);
      }
    });
  }

  // 初期化
  async function initialize() {
    try {
      setupEventListeners();
      await loadUsers();
      await loadHistories();
    } catch (error) {
      window.aivicNotify.error("画面の初期化に失敗しました");
    }
  }

  // 初期化実行
  initialize();
}
